document.addEventListener('DOMContentLoaded', () => {
    const dialog = document.getElementById('delete-dialog');
    const trigger = document.getElementById('delete-trigger');
    const closeButtons = dialog.querySelectorAll('[data-close]');
    const confirmButton = dialog.querySelector('[data-confirm]');

    // Ensure dialog is closed by default if browser doesn't support the element properly
    if (typeof dialog.showModal !== 'function') {
        console.warn('The <dialog> API is not supported by this browser');
    }

    // Open dialog
    trigger.addEventListener('click', () => {
        dialog.showModal();
    });

    // Close on cancel buttons (including the X)
    closeButtons.forEach(btn => {
        btn.addEventListener('click', () => {
            dialog.close('cancel');
        });
    });

    // Handle confirm (delete) action
    confirmButton.addEventListener('click', () => {
        // Here you would typically perform the delete action

        // Remove image from UI to simulate deletion
        const imageWrapper = document.querySelector('.image-wrapper');
        const previewContainer = document.querySelector('.preview-container');

        imageWrapper.style.display = 'none';

        // Show status message
        const statusMsg = document.createElement('p');
        statusMsg.textContent = 'Image deleted successfully.';
        statusMsg.style.textAlign = 'center';
        statusMsg.style.marginTop = '40px';
        statusMsg.setAttribute('role', 'status'); // For accessibility
        statusMsg.setAttribute('tabindex', '-1'); // Make it programmatically focusable

        trigger.parentElement.replaceWith(statusMsg);

        dialog.close('delete');

        // Manage focus since trigger is removed
        statusMsg.focus();
    });

    // Close on backdrop click (clicking outside the dialog)
    dialog.addEventListener('click', (event) => {
        const rect = dialog.getBoundingClientRect();
        const isInDialog = (rect.top <= event.clientY && event.clientY <= rect.top + rect.height &&
                            rect.left <= event.clientX && event.clientX <= rect.left + rect.width);
        if (!isInDialog) {
            dialog.close('cancel');
        }
    });
});
