    <style>
/* style.css */
:root {
    --color-bg: #f9fafb;
    --color-surface: #ffffff;
    --color-text: #111827;
    --color-text-muted: #6b7280;
    --color-danger: #dc2626;
    --color-danger-hover: #b91c1c;
    --color-border: #e5e7eb;
    --color-backdrop: rgba(0, 0, 0, 0.6);

    --radius-lg: 12px;
    --radius-md: 8px;
    --radius-sm: 6px;

    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background-color: var(--color-bg);
    color: var(--color-text);
    line-height: 1.5;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

.visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

.preview-container {
    max-width: 800px;
    margin: 40px auto;
    padding: 20px;
    width: 100%;
}

.image-wrapper {
    background: var(--color-surface);
    border-radius: var(--radius-lg);
    padding: 12px;
    box-shadow: var(--shadow-md);
    margin-bottom: 24px;
}

.preview-image {
    width: 100%;
    height: auto;
    border-radius: var(--radius-md);
    display: block;
}

.actions {
    display: flex;
    justify-content: center;
}

.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 10px 16px;
    font-size: 14px;
    font-weight: 500;
    border-radius: var(--radius-sm);
    border: 1px solid transparent;
    cursor: pointer;
    transition: all 0.2s ease;
    font-family: inherit;
}

.btn:focus-visible {
    outline: 2px solid var(--color-text);
    outline-offset: 2px;
}

.btn-secondary {
    background-color: var(--color-surface);
    border-color: var(--color-border);
    color: var(--color-text);
}

.btn-secondary:hover {
    background-color: var(--color-bg);
}

.trigger {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 10px 16px;
    font-size: 14px;
    font-weight: 500;
    border-radius: var(--radius-sm);
    border: 1px solid transparent;
    cursor: pointer;
    transition: all 0.2s ease;
    font-family: inherit;
    background-color: var(--color-danger);
    color: white;
}

.trigger:hover {
    background-color: var(--color-danger-hover);
}

.trigger:focus-visible {
    outline: 2px solid var(--color-danger);
    outline-offset: 2px;
}

.btn-danger {
    background-color: var(--color-danger);
    color: white;
}

.btn-danger:hover {
    background-color: var(--color-danger-hover);
}

.btn-danger:focus-visible {
    outline: 2px solid var(--color-danger);
    outline-offset: 2px;
}


/* Dialog Styling */
dialog {
    padding: 0;
    border: none;
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-xl);
    max-width: 480px;
    width: 90%;
    margin: auto;
    background: var(--color-surface);
    color: var(--color-text);
}

dialog::backdrop {
    background: var(--color-backdrop);
    backdrop-filter: blur(2px);
}

.dialog-content {
    display: flex;
    flex-direction: column;
}

.dialog-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 20px 24px 16px;
    border-bottom: 1px solid var(--color-border);
}

.dialog-header h2 {
    font-size: 18px;
    font-weight: 600;
    margin: 0;
}

.btn-close {
    background: transparent;
    border: none;
    color: var(--color-text-muted);
    cursor: pointer;
    padding: 4px;
    border-radius: var(--radius-sm);
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
}

.btn-close:hover {
    background: var(--color-bg);
    color: var(--color-text);
}

.btn-close:focus-visible {
    outline: 2px solid var(--color-text);
    outline-offset: 2px;
}

.dialog-body {
    padding: 24px;
}

.dialog-body p {
    color: var(--color-text-muted);
    margin: 0;
    font-size: 14px;
}

.dialog-footer {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    padding: 16px 24px;
    background: var(--color-bg);
    border-top: 1px solid var(--color-border);
    border-radius: 0 0 var(--radius-lg) var(--radius-lg);
}

/* Fallback for dialog when native isn't supported */
dialog:not([open]) {
    display: none;
}

</style>
</head>
<body>
    <main class="preview-container">
        <h1 class="visually-hidden">Image Preview</h1>

        <div class="image-wrapper">
            <img src="https://images.unsplash.com/photo-1550684848-fac1c5b4e853?ixlib=rb-4.0.3&auto=format&fit=crop&w=1000&q=80" alt="A scenic view of mountains at sunset" class="preview-image">
        </div>

        <div class="actions">
            <!-- The control that opens the dialog MUST have a class of "trigger" -->
            <button type="button" class="trigger" id="delete-trigger">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18"></path><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"></path><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>
                Delete Image
            </button>
        </div>
    </main>

    <!-- Native dialog provides built-in accessibility for modals, is closed by default -->
    <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-desc">
        <div class="dialog-content">
            <div class="dialog-header">
                <h2 id="dialog-title">Delete Image?</h2>
                <button type="button" class="btn-close" aria-label="Close dialog" data-close>
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                </button>
            </div>

            <div class="dialog-body">
                <p id="dialog-desc">Are you sure you want to delete this image from your library? This action cannot be undone.</p>
            </div>

            <div class="dialog-footer">
                <button type="button" class="btn btn-secondary" value="cancel" data-close>Cancel</button>
                <button type="button" class="btn btn-danger" value="delete" data-confirm>Delete</button>
            </div>
        </div>
    </dialog>

    <script>
// script.js
document.addEventListener('DOMContentLoaded', () => {
    const dialog = document.getElementById('delete-dialog');
    const trigger = document.getElementById('delete-trigger');
    const closeButtons = dialog.querySelectorAll('[data-close]');
    const confirmButton = dialog.querySelector('[data-confirm]');

    // Ensure dialog is closed by default if browser doesn't support the element properly
    if (typeof dialog.showModal !== 'function') {
        console.warn('The <dialog> API is not supported by this browser');
    }

    // Open dialog
    trigger.addEventListener('click', () => {
        dialog.showModal();
    });

    // Close on cancel buttons (including the X)
    closeButtons.forEach(btn => {
        btn.addEventListener('click', () => {
            dialog.close('cancel');
        });
    });

    // Handle confirm (delete) action
    confirmButton.addEventListener('click', () => {
        // Here you would typically perform the delete action

        // Remove image from UI to simulate deletion
        const imageWrapper = document.querySelector('.image-wrapper');
        const previewContainer = document.querySelector('.preview-container');

        imageWrapper.style.display = 'none';

        // Show status message
        const statusMsg = document.createElement('p');
        statusMsg.textContent = 'Image deleted successfully.';
        statusMsg.style.textAlign = 'center';
        statusMsg.style.marginTop = '40px';
        statusMsg.setAttribute('role', 'status'); // For accessibility
        statusMsg.setAttribute('tabindex', '-1'); // Make it programmatically focusable

        trigger.parentElement.replaceWith(statusMsg);

        dialog.close('delete');

        // Manage focus since trigger is removed
        statusMsg.focus();
    });

    // Close on backdrop click (clicking outside the dialog)
    dialog.addEventListener('click', (event) => {
        const rect = dialog.getBoundingClientRect();
        const isInDialog = (rect.top <= event.clientY && event.clientY <= rect.top + rect.height &&
                            rect.left <= event.clientX && event.clientX <= rect.left + rect.width);
        if (!isInDialog) {
            dialog.close('cancel');
        }
    });
});

</script>
</body>
</html>
